use vstd::prelude::*;

verus! {

/// Specification-level predicate for oddness on integers.
spec fn is_odd_int(x: int) -> bool {
    x % 2 != 0
}

/// The exact required output as a spec function.
spec fn expected_output(n: int) -> Seq<char> {
    if is_odd_int(n) {
        "black\n"@  // Seq<char>
    } else {
        "white\n1 2\n"@
    }
}

fn solve(n: i8) -> (result: String)
    requires
        // Problem statement: input is at least 2.
        n >= 2,
    ensures
        // Strong postcondition: the returned string matches exactly (including newlines/spaces).
        result@ == expected_output(n as int),
        // Equivalent explicit split (sometimes convenient for callers/proofs):
        is_odd_int(n as int) ==> result@ == "black\n"@,
        !is_odd_int(n as int) ==> result@ == "white\n1 2\n"@,
{
    if n % 2 != 0 {
        let s = String::from("black\n");
        proof {
            assert(is_odd_int(n as int));
            assert(expected_output(n as int) == "black\n"@);
        }
        s
    } else {
        let s = String::from("white\n1 2\n");
        proof {
            assert(!is_odd_int(n as int));
            assert(expected_output(n as int) == "white\n1 2\n"@);
        }
        s
    }
}

} // verus!

